// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, description, pixelWidth, pixelHeight}, i) => ({
      image: src, description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (material.answersFile ?? (reviewedKey ? 'reviewed-' + grade : grade + '-answers') + '.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2022, "10-11", [{"author":"П. Аркадьев","question":"Какое словосочетание по смыслу устроено не так, как другие?","choices":["<em>продукты горения</em>","<em>продукты питания</em>","<em>продукты распада</em>","<em>продукты синтеза</em>","все словосочетания (А)–(Г) устроены по смыслу одинаково."],"key":"Б","review":["Что называют продуктами","«Продукты горения», «продукты распада» и «продукты синтеза» образуются в результате названного процесса.","«Продукты питания» нужны для питания. Здесь второе слово обозначает назначение, а не причину появления."]},{"author":"Б. Иомдин","question":"К какому слову можно добавить суффиксы <em>-ист</em> и <em>-ёр</em> и получить существительные с разными значениями — одушевлённое и неодушевлённое?","choices":["<em>пейзаж</em>","<em>массаж</em>","<em>шантаж</em>","<em>монтаж</em>","<em>стаж</em>."],"key":"Б","review":["Суффиксы и значение","Ищи пару, в которой одно слово называет человека, а второе — прибор. Похожие суффиксы сами по себе могут образовывать оба вида названий.","«Массажист» делает массаж, а «массажёр» — приспособление для массажа. Оба слова образуются от «массаж»."]},{"author":"О. Подлесская","question":"В какой паре слова соотносятся друг с другом по смыслу не так, как в остальных?","choices":["<em>аллея — аллейка</em>","<em>аптека — аптечка</em>","<em>ресторан — ресторанчик</em>","<em>рынок — рыночек</em>","<em>сквер — скверик</em>."],"key":"Б","review":["Уменьшительные значения","Аллейка — маленькая аллея, ресторанчик — небольшой ресторан. Рыночек и скверик устроены так же.","Аптечкой называют набор или коробку с лекарствами. Это другой предмет, а не маленькая аптека."]},{"author":"Б. Иомдин","question":"В какой паре даны синонимы?","choices":["<em>удачный, удачливый</em>","<em>опасный, опасливый</em>","<em>занудный, занудливый</em>","<em>отчётный, отчётливый</em>","<em>расчётный, расчётливый</em>."],"key":"В","review":["Пара синонимов","В большинстве пар различаются признак предмета и черта человека. Например, план может быть удачным, а человек — удачливым.","«Занудный» и «занудливый» описывают того, кто утомляет назойливостью и однообразием. Эти прилагательные близки по значению."]},{"author":"М. Рубинштейн","question":"В каком предложении сочетание слов <em>как следует</em> употреблено не так, как в остальных?","choices":["<em>Построением покажите, где и как следует расположить экран, чтобы одновременно получить на нём чёткие изображения обеих точек</em>. (Владимир Лукашик, Елена Иванова)","<em>Кроме того, он знал с точностью физиолога и боксёра, куда и как следует бить человека.</em> (Юрий Домбровский)","<em>Та лучше его знала, как следует жарить котлеты, отбивать бифштексы и варить борщ</em>. (Василь Быков)","<em>От долгого купания я продрог, но, не успев как следует отогреться на берегу, снова лез в воду.</em> (Фазиль Искандер)","<em>И ночью, подъезжая на такси, я до сих пор открываю рот, чтобы сказать шофёру, как следует остановиться, но спохватываюсь: шофёру Дерево невидимо</em>. (Андрей Битов)"],"key":"Г","review":["«Как следует»","В примерах об экране, боксе, готовке и остановке можно спросить «как именно нужно это сделать?». Слово «как» присоединяет косвенный вопрос.","«Не успев как следует отогреться» означает «не успев достаточно хорошо отогреться». Здесь два слова образуют единый оборот."]},{"author":"Л. Фёдорова","question":"Какое из этих слов, называющих развлечения и игры, не русское по происхождению?","choices":["<em>качели</em>","<em>карусель</em>","<em>прятки</em>","<em>ручеёк</em>","<em>жмурки</em>."],"key":"Б","review":["Названия игр","«Качели» связаны с «качать», «прятки» — с «прятать», «ручеёк» — с «ручей», «жмурки» — с «жмуриться». Их можно сопоставить с русскими основами.","«Карусель» пришло из другого языка. В русском оно стало названием вращающегося аттракциона."]},{"author":"А. Пиперски","question":"Если ввести в поисковую систему Google запрос «шашлык по», она предложит несколько различных продолжений. Одно из них по смыслу явно отличается от четырёх других. Какое?","choices":["<em>шашлык по-карски</em>","<em>шашлык по-грузински</em>","<em>шашлык по-армянски</em>","<em>шашлык по-английски</em>","<em>шашлык по-кавказски.</em>"],"key":"Г","review":["Как говорят о шашлыке","Карс, Грузия, Армения и Кавказ отсылают к кухне Кавказа и соседних регионов. В этих вариантах речь о местном способе приготовления.","«Шашлык по-английски» можно понимать как название шашлыка на английском языке. Это другой смысл сочетания."]},{"author":"Б. Иомдин","question":"В каком примере слово <em>весёленький</em> означает совсем не то, что в остальных?","choices":["«<em>Весёленькая передо мной перспектива», — вздохнула она</em>. (В. Аксёнов)","<em>Н-да. Весёленький номер сейчас будет</em>. (А. Пантелеев)","<em>Весёленькая, чистенькая, не налюбуешься на тебя!</em> (М. Рощин)","<em>Весёленькое получается дельце, нечего сказать</em>. (Е. Сухов)","«<em>У каждого врача своё кладбище», — сказала медсестра. Весёленькие, бодрящие разговоры.</em> (Д. Каралис)"],"key":"В","review":["«Весёленький» в отрывках","«Весёленькая перспектива», «весёленький номер», «весёленькое дельце» и «весёленькие разговоры» сказаны иронически. Ситуация в них неприятная.","В обращении «Весёленькая, чистенькая, не налюбуешься на тебя!» похвала искренняя. Слово употреблено в прямом смысле."]},{"author":"И. Рубанов","question":"<em>Абрикос</em>, <em>кокос</em>, <em>газонокосилка</em>, <em>косинус</em>, <em>молокосос</em>, <em>откос</em>. Сколько в этом списке слов, в которых выделяется корень -<em>кос-</em>?","choices":["одно","два","три","четыре","пять."],"key":"Б","review":["Где есть корень «кос»","Совпадение букв ещё не означает совпадения корня. Например, в «молокососе» К относится к «молоко», а дальше начинается «сос».","В «газонокосилке» есть корень «кос-» от «косить», а в «откосе» — корень с тем же написанием со значением наклона. Таких слов два."]},{"author":"И. Иткин","question":"<em>Баркарола</em> — это песня __________.","choices":["миланских оперных певцов","венецианских лодочников","римских нищих","неаполитанских полицейских","туринских футбольных болельщиков."],"key":"Б","review":["Песня на воде","Начало «баркаролы» связано с итальянским «barca» — «лодка». Ищем тех, кто поёт, управляя лодкой.","Баркарола — песня венецианских лодочников, гондольеров. Её плавный ритм напоминает движение лодки."]},{"author":"Е. Бикмаев","question":"В романе Марка Твена про короля Артура читаем: <em>«Приближённые короля Артура не сознавали, что они невоспитанны, а я был настолько _______, что не дал им этого заметить»</em>. Какое слово мы пропустили?","choices":["<em>невнимателен</em>","<em>бесчувствен</em>","<em>неосторожен</em>","<em>бестактен</em>","<em>тактичен</em>."],"key":"Д","review":["Тактичность рассказчика","Рассказчик заметил чужую невоспитанность, но сделал так, чтобы собеседникам не пришлось смущаться.","Так себя ведёт тактичный человек. Нужна короткая форма «тактичен»."]},{"author":"Е. Муравенко","question":"Какое из слов можно прочитать по-разному в зависимости от значения?","choices":["<em>нарочно</em>","<em>срочно</em>","<em>скучно</em>","<em>конечно</em>","<em>вечно</em>."],"key":"Г","review":["Произношение ЧН","В ответе «Конечно!» обычно произносят [шн]. Это вводное слово со смыслом уверенности.","В математической фразе «множество конечно» слово значит «имеет конец, ограничено». Здесь произносят [чн], поэтому произношение зависит от значения."]},{"author":"Е. Муравенко и И. Рубанов","question":"<em>На конференцию приехали гости __________.</em>\n1) из зарубежа; 2) из зарубежных стран,\n3) из-за рубежа, 4) из-за рубежных стран.\nКакие варианты правильны?","choices":["только 1","только 2","1 и 2","2 и 3","3 и 4."],"key":"Г","review":["Откуда приехали гости","Можно сказать «из зарубежных стран» или «из-за рубежа». В первом случае предлог относится к «странам», во втором — к «рубежу».","Формы «из зарубежа» и «из-за рубежных стран» не подходят. Верны варианты 2 и 3."]},{"author":"Б. Иомдин","question":"В четырёх словосочетаниях обычно слово <em>дурацкий</em> переводится на английский язык словом <em>idiotic</em>, а в пятом — другим словом. В каком? (Знание английского языка для решения задачи не требуется.)","choices":["<em>дурацкие штаны</em>","<em>дурацкое платье</em>","<em>дурацкий колпак</em>","<em>дурацкий сарафан</em>","<em>дурацкие валенки</em>."],"key":"В","review":["Смысл слова «дурацкий»","Штаны, платье, сарафан или валенки можно оценить как нелепые. У прилагательного тогда значение «глупый, неудачный».","«Дурацкий колпак» может означать головной убор шута. Прилагательное называет принадлежность, и перевод будет другим."]},{"author":"И. Рубанов","question":"Из названия какой греческой буквы можно перестановкой букв получить название латинской буквы?","choices":["<em>бета</em>","<em>кси</em>","<em>пси</em>","<em>тау</em>","<em>эта</em>."],"key":"Б","review":["Буква из перестановки","Проверь, какие названия латинских букв можно собрать из трёхбуквенных названий греческих.","В слове «кси» переставляем буквы и получаем «икс», название X."]},{"author":"Е. Муравенко","question":"В какой из пар слова состоят не только из одинаковых букв, но и из одинаковых звуков?","choices":["<em>корма — комар</em>","<em>весна — навес</em>","<em>бокал — колба</em>","<em>лето — тело</em>","<em>сруб — брус</em>."],"key":"А","review":["Перестановка звуков","«Корма́» и «кома́р» начинаются с [к] и безударного гласного, который звучит одинаково. Ударный гласный в обеих формах — [а].","Набор согласных [к], [р], [м] тоже совпадает. Поэтому у «корма» и «комар» совпадают и буквы, и звуки."]},{"author":"П. Долгополов","question":"В Польше слово stop можно увидеть не только на дорожных знаках, но и в учебниках химии. В последнем случае это исконно славянское слово, которое означает _____.","choices":["‘яд’","‘спирт’","‘газ’","‘сплав’","‘пар’."],"key":"Г","review":["Слово «stop» в химии","Польское «stop» можно связать с глаголом «stopić» — расплавить. Подумай, что получают, если вместе расплавить металлы.","Так получают сплав. Термин родственен словам о плавлении, а знак на дороге имеет другое происхождение."]},{"author":"А. Остроумова","question":"Одна компьютерная программа не знает русские фамилии и подчёркивает их как несуществующие слова. Однако среди следующих фамилий она подчеркнёт только одну. Какую?","choices":["<em>Дьяков</em>","<em>Крылов</em>","<em>Львов</em>","<em>Рыжиков</em>","<em>Туров</em>."],"key":"Б","review":["Сходство фамилии и слова","Программа пропустит фамилию, если она совпала с другой словоформой. Можно встретить «дьяков», «львов», «рыжиков» и «туров» как формы обычных существительных.","У «крыло» родительный множественного числа «крыльев». Написание «Крылов» не совпадает с этой формой и будет подчёркнуто."]},{"author":"О. Подлесская","question":"В письме художника И. И. Шишкина, написанном родным в 1856 г., мы заменили прочерком формы одного и того же слова три раза: «Нанял себе … комнату особую ценою в месяц 3 рубля 50 копеек серебром без _____, квартиры со _____ здесь много дороже московского, потому я рассудил не иметь постоянного _____...». Какое это слово?","choices":["<em>буфет</em>","<em>шкаф</em>","<em>стол</em>","<em>свет</em>","<em>интернет</em>."],"key":"В","review":["Комната и питание","Во всех пропусках нужны формы одного слова. У него должно быть значение услуги, из-за которой жильё обходилось дороже.","Слово «стол» могло означать питание. Получаются «без стола», «квартиры со столом» и «не иметь постоянного стола»."]},{"author":"А. Сомин","question":"Какая из этих последовательностей почти не встречается без дефиса в правильно написанных текстах?","choices":["<em>во-первых</em>","<em>во-вторых</em>","<em>в-третьих</em>","<em>в-десятых</em>","никакая из этих последовательностей не встречается без дефиса в правильных текстах."],"key":"А","review":["Когда возможен пробел","Числительные можно использовать после предлога с существительным: «во вторых классах», «в третьих рядах», «в десятых числах».","Когда речь о первых рядах, обычно говорят «в первых рядах». Форма «во-первых» почти всегда служит вводным словом и пишется с дефисом."]},{"author":"И. Рубанов","question":"Какое из данных в ответах прилагательных чаще других сочетается со словом <em>столб</em>?","choices":["<em>миллиметровый</em>","<em>сантиметровый</em>","<em>дециметровый</em>","<em>метровый</em>","<em>километровый</em>."],"key":"Д","review":["Столбы вдоль дороги","Название меры может говорить о высоте столба, но есть и особые столбы, которыми отмечают расстояния на дороге.","Каждый километровый столб обозначает пройденный километр. Это привычное сочетание чаще, чем указание размеров столба в остальных вариантах."]},{"author":"С. Дьяченко","question":"Одно значение этого глагола связано с капельками воды, другое — с вырвавшимся смехом. А какое значение имеет однокоренное этому глаголу приставочное существительное?","choices":["потомок","вид танца","птица","средство передвижения","каток."],"key":"А","review":["Вода, смех и родство","«Прыснуть» может значить брызнуть жидкостью или вдруг рассмеяться.","В слове «отпрыск» тот же корень с приставкой «от-». «Отпрыск» означает потомка."]},{"author":"Л. Фёдорова","question":"<em>Прошло сто лет — и юный град,\nПолнощных стран краса и диво,\nИз тьмы лесов, из топи блат\nВознёсся пышно, горделиво…</em> (А. С. Пушкин)\nЧто означает здесь <em>полнощных</em>?","choices":["тёмных","древних","западных","мощных","северных."],"key":"Д","review":["Значение старого слова","Старинная «полнощь» означала полночь. В старой речи «полнощный» противопоставляли «полуденному», то есть южному.","В строках о Петербурге «полнощные страны» — северные страны. Это указание на север."]},{"author":"А. Сомин","question":"Один сайт требует от пользователя выбрать нужный язык из алфавитного списка языков. Нидерландский язык, однако, находится в этом списке в неправильном месте: по всей видимости, эта ошибка — результат редактирования. А между какими двумя языками он оказался?","choices":["между кхмерским и лаосским","между финским и французским","между мальтийским и монгольским","между венгерским и греческим","между португальским и румынским."],"key":"Г","review":["Язык в алфавитном списке","У нидерландского языка бывает другое название — «голландский». Возможно, его заменили в списке, а строку оставили на прежнем месте.","«Голландский» по алфавиту стоит после «венгерского» и перед «греческим». Там и оказался «нидерландский»."]},{"author":"А. Сомин","question":"Какое из этих словосочетаний сильно отличается по смыслу от других?","choices":["<em>однобуквенные слова</em>","<em>односложные слова</em>","<em>однозначные слова</em>","<em>однокоренные слова</em>","<em>одноударные слова</em>."],"key":"Г","review":["У каждого или у группы","«Однобуквенное», «односложное», «однозначное» и «одноударное» описывают устройство одного слова: в нём одна буква, слог, значение или ударение.","«Однокоренными» называют слова по отношению друг к другу. У нескольких слов совпадает корень, и это об их сходстве."]},{"author":"И. Рубанов","question":"<em>Бронхит</em>, <em>еда</em>, <em>недостаток</em>, <em>тема</em>, <em>ум</em>. Сколько из этих слов сочетаются с прилагательным <em>острый</em>?","choices":["одно","два","три","четыре","все пять."],"key":"Д","review":["Разные смыслы «острый»","В медицине говорят «острый бронхит». О еде можно сказать, что она острая, если вкус жгучий, а об уме — если он проницательный.","«Острый недостаток» — значительная нехватка, «острая тема» — та, что сильно волнует. Прилагательное подходит ко всем пяти словам."]},{"author":"А. Пучкова и П. Наследскова","question":"Даны несколько предложений на рутульском языке:\nRɨš sarχɨra ‘Девочка спит’\nSa rɨš argɨr ‘Одна девочка остаётся’\nRɨšbe sadχɨra ‘Девочки спят’\nWeš rɨš sadχɨra ‘Сто девочек спят’\nИзвестно, что слово xibɨr значит ‘три’. Даны ещё пять предложений на рутульском языке. Какие два из них являются правильными? (На рутульском языке говорит около 30 тыс. чел. в Республике Дагестан. Буквы x и χ читаются примерно как русское х, š — как ш, ɨ — как ы.)\n(1) Rɨšbe adgɨr; (2) Weš rɨš sarχɨra; (3) Sa rɨš sadχɨra; (4) Xibɨr rɨšbe adgɨr; (5) Xibɨr rɨš sadχɨra","choices":["1 и 2","1 и 4","3 и 4","4 и 5","1 и 5."],"key":"Д","review":["Число в рутульском языке","После числительного «сто» слово «девочка» стоит без окончания «-be», как после слова «одна». Глагол при ста девочках, однако, совпадает с глаголом во множественном числе.","При «три» получаем «Xibɨr rɨš sadχɨra», это пример 5. В 1-м примере без числительного «Rɨšbe adgɨr» означает, что девочки остаются. Подходят 1 и 5."]},{"author":"Б. Иомдин","question":"Автор словаря изучал существительные, называющие то, что могут поставлять поставщики. Какой пример ему не подошёл?","choices":["<em>Рыночные отношения вывели на первый план поставщиков продовольствия из других стран</em>.","<em>Наша женская сборная в мировом биатлоне — реальная сила, поставщик талантов</em>.","<em>Но главным поставщиком новостей о мирах за пределами Солнечной системы остаётся телескоп «Кеплер»</em>.","<em>Аналитики сулят непростые времена традиционным поставщикам дорогих углеводородов</em>.","<em>«Восток-Запад» — крупнейший поставщик ресторанов и кондитерских производств в России</em>."],"key":"Д","review":["Кого или что поставляют","В первых четырёх примерах зависимое слово обозначает то, что поставляют: продукты, таланты, новости или углеводороды.","В примере о ресторанах рестораны получают товары, а не служат товаром. Зависимое слово обозначает получателя."]},{"author":"Л. Фёдорова","question":"Найдите пару исторически родственных слов в данном списке:\n1) <em>воля</em>, 2) <em>влияние</em>, 3) <em>ливень</em>, 4) <em>лавина</em>, 5) <em>волнение</em>.","choices":["1 и 2","1 и 5","2 и 3","3 и 4","2 и 5."],"key":"В","review":["Влияние и ливень","Сравни «ливень» с глаголом «лить». У «влияния» в основе есть форма «влиять», по происхождению связанная с «вливать».","Общий старый корень сохранился в словах о течении и литье. Исторически родственны «влияние» и «ливень»."]},{"author":"А. Пиперски","question":"Даны три фрагмента из драматической поэмы Николая Гумилёва «Гондла»:\n(1) <em>Гондла добыл великую славу / И великую дал нам печаль.</em>\n(2) <em>Дальше поплыли, ветры бесились, / Как гуляки, у нас на пути.</em>\n(3) <em>Счастья мера, а муки безмерность — / Вот вся жизнь; но я жив, не таю</em>…\nВ каком (каких) из них есть ударный звук [ы]?","choices":["во всех","только в 1 и 2","только в 1","только в 2 и 3","только в 3."],"key":"Д","review":["Звук Ы в стихах","Ритм первых двух отрывков подсказывает ударения «до́был» и «по́плыли»: ударные слоги совпадают с сильными местами соседних слов. Буква Ы в этих формах без ударения.","В третьем отрывке произносим «жизнь» и «жив». После всегда твёрдого Ж буква И передаёт ударный звук [ы]. Подходит только третий отрывок."]}], {"year":2022,"grade":"10-11","tasksFile":"10-11.pdf","answersFile":"10-11-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2022-1.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
